def solve(I):
    H,W=len(I),len(I[0])
    objs={}
    for i,r in enumerate(I):
        for j,x in enumerate(r):
            if x: objs.setdefault(x,[]).append((i,j))
    out=[[0]*W for _ in range(H)]
    # order: rightmost first (min col desc)
    order=sorted(objs.keys(), key=lambda v:min(j for _,j in objs[v]), reverse=True)
    placed=set()
    for v in order:
        ps=objs[v]
        c=min(j for _,j in ps)
        # max shift right without overlap with any placed obj
        def ok(s):
            for i,j in ps:
                ii,i=j,s=i+s; ii=i; jj=j+s  # messy
            return True
        best=0
        for s in range(1, W-c):
            bad=False
            for i,j in ps:
                ni,nj=i,j+s
                if (ni,nj) in placed: bad=True; break
            if bad: break
            best=s
        for i,j in ps:
            ni,nj=i,j+best
            out[ni][nj]=v
            placed.add((ni,nj))
    return out
